          const targetOffset = pageToOffset(currentPage);
          scrollToOffset(targetOffset, smooth);
          emitPageUpdate();
          log("jumpToPage", {
            targetPage: currentPage + 1,
            totalPages,
            smooth: Boolean(smooth),
            targetOffset,
