        }

        function syncPageFromScroll() {
          const inferredPage = offsetToPage(getCurrentOffset());

          if (inferredPage !== currentPage) {
            currentPage = inferredPage;
            emitPageUpdate();
          }
        }

        function nextPage() {
          jumpToPage(currentPage + 1, true);
        }

        function previousPage() {
          jumpToPage(currentPage - 1, true);
