          const textNodes = [];
          collectLookupTextNodes(containerNode, textNodes);
          if (textNodes.length === 0) {
            return { entries: [], joinedText: "" };
          }

          const entries = [];
          let cursor = 0;
          let joinedText = "";

          textNodes.forEach(function (node) {
            const text = node.textContent || "";
            const start = cursor;
            const end = start + text.length;

            entries.push({
              node,
              start,
              end,
            });
            cursor = end;
            joinedText += text;
          });

